//! 🖊️ Fixed-state SVG endpoint arcs and exact Beziers publish one funded affine path command.
use super::geometry::DrawingAffine;
use semio_framework_io_ports::{VectorSegment,VectorPoint2};
use semio_framework_2d_engine::PathSegment;
use semio_framework_value::{ValueError,ValueRefusalKind};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Drawing segment contract is invalid")}
fn point(p:VectorPoint2)->Result<VectorPoint2,ValueError>{if p.x.is_finite()&&p.y.is_finite(){Ok(p)}else{Err(invalid())}}
fn tuple(p:VectorPoint2)->[f64;2]{[p.x,p.y]}
fn unit_error(span:f64)->f64{let half=span*0.5;let k=4.0/3.0*(span*0.25).tan();let a=4.0*half.sin()-6.0*k*half.cos();let square=a*a/432.0;square/((1.0+square).sqrt()+1.0)}
#[derive(Clone,Copy)]
struct Arc{center:VectorPoint2,u:VectorPoint2,v:VectorPoint2,start:f64,delta:f64,pieces:u32,at:u32,end:VectorPoint2}
/// 🚦️ One retained source command yields no more than one owned geometric command per funded turn.
pub struct DrawingSegmentStep{pub work:u64,pub segment:Option<PathSegment>,pub pending:bool}
/// 🧵️ All state is scalar; cancellation and completed commands own no allocated backing.
#[derive(Clone,Copy)]
pub struct DrawingSegmentCursor{tolerance:f64,command:Option<VectorSegment>,affine:DrawingAffine,pen:Option<VectorPoint2>,start:Option<VectorPoint2>,arc:Option<Arc>,work:u64,cancelled:bool}
semio_framework_value::artifact_retire_leaf!(DrawingSegmentCursor);
impl DrawingSegmentCursor{
 pub fn new(tolerance:f64)->Result<Self,ValueError>{if !tolerance.is_finite()||tolerance<=0.0{return Err(invalid())}Ok(Self{tolerance,command:None,affine:DrawingAffine::identity(),pen:None,start:None,arc:None,work:0,cancelled:false})}
 pub fn accept(&mut self,command:VectorSegment,affine:DrawingAffine)->Result<(),ValueError>{if self.cancelled||self.pending()||![affine.xx,affine.xy,affine.yx,affine.yy,affine.dx,affine.dy].into_iter().all(f64::is_finite){return Err(invalid())}if !matches!(command,VectorSegment::MoveTo{..}|VectorSegment::Close)&&self.pen.is_none(){return Err(invalid())}match command{VectorSegment::MoveTo{to}|VectorSegment::LineTo{to}=>{point(to)?;},VectorSegment::QuadTo{c,to}=>{point(c)?;point(to)?;},VectorSegment::CubicTo{c1,c2,to}=>{point(c1)?;point(c2)?;point(to)?;},VectorSegment::ArcTo{rx,ry,x_rotation,to,..}=>{point(to)?;if ![rx,ry,x_rotation].into_iter().all(f64::is_finite){return Err(invalid())}},VectorSegment::Close=>{}}self.command=Some(command);self.affine=affine;Ok(())}
 fn prepare_arc(&self,from:VectorPoint2,rx:f64,ry:f64,degrees:f64,large:bool,sweep:bool,to:VectorPoint2)->Result<Arc,ValueError>{let(mut rx,mut ry)=(rx.abs(),ry.abs());let(s,c)=(degrees%360.0).to_radians().sin_cos();let(dx,dy)=(from.x*0.5-to.x*0.5,from.y*0.5-to.y*0.5);let(x,y)=(c*dx+s*dy,-s*dx+c*dy);let mut norm=(x/rx).hypot(y/ry);if !norm.is_finite(){let first=x.hypot(y*(rx/ry));let second=(x*(ry/rx)).hypot(y);rx=first;ry=second;norm=(x/rx).hypot(y/ry);}else if norm>1.0{rx*=norm;ry*=norm;norm=(x/rx).hypot(y/ry);}if ![rx,ry,norm].into_iter().all(f64::is_finite)||norm==0.0{return Err(invalid())}let sign=if large==sweep{-1.0}else{1.0};let root=sign*(1.0-norm*norm).max(0.0).sqrt();let(cx,cy)=(rx*(y/ry/norm)*root,-ry*(x/rx/norm)*root);let a=self.affine;let center=a.map(VectorPoint2{x:c*cx-s*cy+from.x*0.5+to.x*0.5,y:s*cx+c*cy+from.y*0.5+to.y*0.5})?;let u=point(VectorPoint2{x:rx*(a.xx*c+a.xy*s),y:rx*(a.yx*c+a.yy*s)})?;let v=point(VectorPoint2{x:ry*(-a.xx*s+a.xy*c),y:ry*(-a.yx*s+a.yy*c)})?;let(ux,uy,vx,vy)=((x-cx)/rx,(y-cy)/ry,(-x-cx)/rx,(-y-cy)/ry);let start=uy.atan2(ux);let mut delta=(ux*vy-uy*vx).atan2(ux*vx+uy*vy);if !sweep&&delta>0.0{delta-=std::f64::consts::TAU}else if sweep&&delta<0.0{delta+=std::f64::consts::TAU}let bound=u.x.hypot(u.y)+v.x.hypot(v.y);if !bound.is_finite(){return Err(invalid())}let mut pieces=(delta.abs()/std::f64::consts::FRAC_PI_2).ceil().max(1.0)as u32;while bound*unit_error(delta.abs()/f64::from(pieces))>self.tolerance{pieces=pieces.checked_mul(2).ok_or_else(invalid)?;}Ok(Arc{center,u,v,start,delta,pieces,at:0,end:a.map(to)?})}
 pub fn advance(&mut self,grant:usize)->Result<DrawingSegmentStep,ValueError>{if self.cancelled{return Err(invalid())}if grant==0||!self.pending(){return Ok(DrawingSegmentStep{work:self.work,segment:None,pending:self.pending()})}self.work=self.work.checked_add(1).ok_or_else(invalid)?;let segment=if let Some(arc)=self.arc.as_mut(){let from=arc.start+arc.delta*f64::from(arc.at)/f64::from(arc.pieces);let end=arc.start+arc.delta*f64::from(arc.at+1)/f64::from(arc.pieces);let k=4.0/3.0*((end-from)*0.25).tan();let p=|t:f64|VectorPoint2{x:arc.center.x+arc.u.x*t.cos()+arc.v.x*t.sin(),y:arc.center.y+arc.u.y*t.cos()+arc.v.y*t.sin()};let d=|t:f64|VectorPoint2{x:-arc.u.x*t.sin()+arc.v.x*t.cos(),y:-arc.u.y*t.sin()+arc.v.y*t.cos()};let p0=p(from);let p3=if arc.at+1==arc.pieces{arc.end}else{p(end)};let d0=d(from);let d1=d(end);let segment=PathSegment::Cubic{ctrl1:tuple(point(VectorPoint2{x:p0.x+k*d0.x,y:p0.y+k*d0.y})?),ctrl2:tuple(point(VectorPoint2{x:p3.x-k*d1.x,y:p3.y-k*d1.y})?),to:tuple(point(p3)?)};arc.at+=1;if arc.at==arc.pieces{self.arc=None;}Some(segment)}else{let source=self.command.take().ok_or_else(invalid)?;let map=|p|self.affine.map(p).map(tuple);match source{VectorSegment::MoveTo{to}=>{self.pen=Some(to);self.start=Some(to);Some(PathSegment::Move{to:map(to)?})},VectorSegment::LineTo{to}=>{self.pen=Some(to);Some(PathSegment::Line{to:map(to)?})},VectorSegment::QuadTo{c,to}=>{self.pen=Some(to);Some(PathSegment::Quad{ctrl:map(c)?,to:map(to)?})},VectorSegment::CubicTo{c1,c2,to}=>{self.pen=Some(to);Some(PathSegment::Cubic{ctrl1:map(c1)?,ctrl2:map(c2)?,to:map(to)?})},VectorSegment::ArcTo{rx,ry,x_rotation,large_arc,sweep,to}=>{let from=self.pen.ok_or_else(invalid)?;self.pen=Some(to);if from.x==to.x&&from.y==to.y{None}else if rx==0.0||ry==0.0{Some(PathSegment::Line{to:map(to)?})}else{self.arc=Some(self.prepare_arc(from,rx,ry,x_rotation,large_arc,sweep,to)?);None}},VectorSegment::Close=>{if self.start.is_some(){self.pen=self.start;}Some(PathSegment::Close)}}};Ok(DrawingSegmentStep{work:self.work,pending:self.pending(),segment})}
 pub fn pending(&self)->bool{self.command.is_some()||self.arc.is_some()}
 pub fn cancel(&mut self){self.cancelled=true;self.command=None;self.arc=None;self.pen=None;self.start=None;}
 pub fn terminal_is_empty(&self)->bool{!self.pending()}
}
#[cfg(test)]#[path="🧪️tests/🦀️.rs"]mod tests;
